/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void prog_err_add (Prog_Error_Code code)
{  
  UInt8 ptr = prog_err.count %PROG_ERR_BUFF_SIZE ;
 
  prog_err.code[ptr] = code ;

  prog_err.count++ ;
  
  prog_err_save() ;
}

